import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:]))

    if 1 not in a:
        print("NO")
    else:
        print("YES")
        result = []
        i = 0
        while i < n:
            if a[i] == 1:
                result.append(str(a[i]))
                i += 1
                while i < n and a[i] == 0:
                    result.append("->(" + str(a[i]) + ")")
                    i += 1
                if i < n:
                    result[-1] = "(" + result[-1][2:] + "->" + str(a[i]) + ")"
                    i += 1
            else:
                result.append(str(a[i]))
                i += 1
        print("".join(result))

if __name__ == "__main__":
    main()
